893	// TestEvaluateCorruptVersionDistinctFromUnknown checks the boundary against
894	// unregistered ids, whole-archive corruption and intact siblings: an
895	// identifier that was never registered stays an unknown version, unreadable
896	// archive JSON stays archive corruption, and a damaged unselected version
897	// neither contaminates an intact candidate nor the built-in version.
898	func TestEvaluateCorruptVersionDistinctFromUnknown(t *testing.T) {
899		dir := setupReviewCorruptArchive(t)
900		submit(t, dir, reviewSub("1", "0xa", "0xd", "displacement", "f", "a", "fp", ReviewStatusFalsePositive, 0))
901		rewriteStoredVersion(t, dir, "mult3", func(ver map[string]any) {
902			delete(storedRule(t, ver, "displacement"), "multiplier")
903		})
904	
905		// Never registered: unknown version, not corruption.
906		if _, err := EvaluateReviews(dir, "1", 0, 100, "ghost"); !errors.Is(err, ErrUnknownVersion) ||
907			errors.Is(err, ErrCorruptVersion) {
908			t.Fatalf("unknown version error = %v", err)
909		}
910		// The built-in version is unaffected by the corrupt sibling.
911		got, err := EvaluateReviews(dir, "1", 0, 100, BuiltinVersionID)
912		if err != nil {
913			t.Fatalf("evaluate under builtin failed: %v", err)
914		}
915		if got.StillHit != 1 || got.Pending != 1 {
916			t.Fatalf("builtin evaluation counts = %+v", got)
917		}
918		if got.Version.ID != BuiltinVersionID {
919			t.Fatalf("candidate version = %+v", got.Version)
920		}
921	
922		// An intact second candidate still evaluates while the corrupt one sits
923		// unselected in the same archive.
924		mustRegisterVersion(t, dir, strictSpec)
925		strict, err := EvaluateReviews(dir, "1", 0, 100, "strict")
926		if err != nil {
927			t.Fatalf("evaluate under intact strict failed: %v", err)
928		}
929		// strict (mult 5) stops the displacement 0xd: the reviewed false
930		// positive is eliminated; the unreviewed sandwich still hits and is
931		// pending.
932		if strict.Eliminated != 1 || strict.Pending != 1 {
933			t.Fatalf("intact candidate counts = %+v", strict)
934		}
935	
936		// Unreadable archive JSON is whole-archive corruption regardless of the
937		// named version.
938		path := filepath.Join(dir, archiveFileName)
939		if err := os.WriteFile(path, []byte("{broken"), 0o644); err != nil {
940			t.Fatal(err)
941		}
942		if _, err := EvaluateReviews(dir, "1", 0, 100, BuiltinVersionID); err == nil ||
943			!strings.Contains(err.Error(), "archive is corrupted") {
944			t.Fatalf("unreadable archive error = %v, want archive corrupted", err)
945		}
946		if _, err := EvaluateReviews(dir, "1", 0, 100, "ghost"); err == nil ||
947			!strings.Contains(err.Error(), "archive is corrupted") {
