1080	// runRejudgmentRace fires n contenders carrying the same valid
1081	// expectedVersion (1, against an object already at version 1) at the same
1082	// instant, each with a distinct submissionId/operator/reason/status, and
1083	// returns the per-submitter outcomes in submission order.
1084	func runRejudgmentRace(t *testing.T, dir string, n int) []raceOutcome {
1085		t.Helper()
1086		outcomes := make([]raceOutcome, n)
1087		var wg sync.WaitGroup
1088		start := make(chan struct{})
1089		for i := 0; i < n; i++ {
1090			wg.Add(1)
1091			go func(i int) {
1092				defer wg.Done()
1093				<-start
1094				outcomes[i].res, outcomes[i].err = SubmitReview(dir, raceSub(i))
1095			}(i)
1096		}
1097		close(start)
1098		wg.Wait()
1099		return outcomes
1100	}
