1102	// verifyRaceSettlement proves the anti-overwrite rules against the history
1103	// actually persisted after a rejudgment race: exactly one contender created
1104	// a revision, the object advanced exactly one version, every stored bit of
1105	// the new revision comes from that winner alone, the original revision and
1106	// the archived conclusion/evidence are untouched, and every loser (busy or
1107	// version conflict) left no content behind.
1108	func verifyRaceSettlement(t *testing.T, dir string, outcomes []raceOutcome, original ReviewRevision) int {
1109		t.Helper()
1110		winner := -1
1111		busyIdx, conflictIdx := -1, -1
1112		for i, o := range outcomes {
1113			switch {
1114			case o.err == nil:
1115				if !o.res.Created || o.res.Version != 2 {
1116					t.Fatalf("submitter %d returned %+v, want created at version 2", i, o.res)
1117				}
1118				if winner != -1 {
1119					t.Fatalf("two successful contenders: %d and %d", winner, i)
1120				}
1121				winner = i
1122			case errors.Is(o.err, ErrBusy):
1123				// The contender hit the lock while another submitter held it.
1124				busyIdx = i
1125			case errors.Is(o.err, ErrReviewConflict):
1126				// The contender entered after the lock was released, read the
1127				// already-bumped version and was rejected on the version check.
1128				conflictIdx = i
1129			default:
1130				t.Fatalf("submitter %d got an outcome other than success/busy/conflict: %v", i, o.err)
1131			}
1132		}
1133		if winner == -1 {
1134			t.Fatal("no contender succeeded")
1135		}
1136		t.Logf("race settled: winner=%d, busy=%d, version-conflict=%d (either loser outcome is valid)",
1137			winner, countOutcomes(outcomes, ErrBusy), countOutcomes(outcomes, ErrReviewConflict))
1138	
1139		winSub := raceSub(winner)
1140		wantRev := winSub.revision(2)
1141		if !reflect.DeepEqual(outcomes[winner].res.Revision, wantRev) {
1142			t.Fatalf("winner result revision = %+v, want %+v", outcomes[winner].res.Revision, wantRev)
1143		}
1144	
1145		hist, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1146		if err != nil {
1147			t.Fatal(err)
1148		}
1149		if hist.Version != 2 || hist.Status != winSub.Status {
1150			t.Fatalf("current state = %q/%d, want %q/2 (the winner's rejudgment)",
1151				hist.Status, hist.Version, winSub.Status)
1152		}
1153		if len(hist.Revisions) != 2 {
1154			t.Fatalf("object holds %d revisions, want exactly 2 (losers must leave none): %+v",
1155				len(hist.Revisions), hist.Revisions)
1156		}
1157		if !reflect.DeepEqual(hist.Revisions[0], original) {
1158			t.Fatalf("original revision not retained first: %+v, want %+v", hist.Revisions[0], original)
1159		}
1160		if !reflect.DeepEqual(hist.Revisions[1], wantRev) {
1161			t.Fatalf("appended revision = %+v, want the winner's %+v", hist.Revisions[1], wantRev)
1162		}
1163		// Defense in depth: no field of any loser may appear in the new
1164		// revision, and no loser submission id may be stored anywhere. Status is
1165		// deliberately excluded because only three legal statuses exist so two
1166		// contenders may legitimately carry the same one; identity/operator/
1167		// reason are unique per submitter and the full-revision DeepEqual above
1168		// already pins the winner's status.
1169		loserIDs := map[string]bool{}
1170		for i := range outcomes {
1171			if i == winner {
1172				continue
1173			}
1174			s := raceSub(i)
1175			loserIDs[s.SubmissionID] = true
1176			stored := hist.Revisions[1]
1177			if stored.SubmissionID == s.SubmissionID || stored.Operator == s.Operator ||
1178				stored.Reason == s.Reason {
1179				t.Fatalf("loser %d content mixed into the stored revision: %+v", i, stored)
1180			}
1181			if reflect.DeepEqual(stored, s.revision(2)) {
1182				t.Fatalf("stored revision is identical to loser %d's content: %+v", i, stored)
1183			}
1184		}
1185		for _, rev := range hist.Revisions {
1186			if loserIDs[rev.SubmissionID] {
1187				t.Fatalf("loser submission id %q left a revision", rev.SubmissionID)
1188			}
1189		}
1190		// The original archived conclusion, its detection parameters and the
1191		// raw swap evidence stay exactly as archived.
1192		if hist.Original == nil ||
1193			hist.Original.Finding.TxHash != "0xv" || hist.Original.Finding.Kind != "sandwich" ||
1194			hist.Original.Finding.Severity != 3 || len(hist.Original.Finding.Evidence) != 3 {
1195			t.Fatalf("original conclusion/evidence changed: %+v", hist.Original)
1196		}
1197		if hist.Original.Version.ID != BuiltinVersionID {
1198			t.Fatalf("detection version changed: %+v", hist.Original.Version)
1199		}
1200	
1201		// After the race, resubmitting with the stale expected version must be a
1202		// version conflict regardless of how the contender originally lost: a
1203		// busy loss is not a completed rejudgment, and neither path may overwrite
1204		// the winner.
1205		recheck := func(idx int, label string) {
1206			if idx < 0 {
1207				return
1208			}
1209			if _, err := SubmitReview(dir, raceSub(idx)); !errors.Is(err, ErrReviewConflict) {
1210				t.Fatalf("%s loser (submitter %d) replayed with original expected version: got %v, want ErrReviewConflict",
1211					label, idx, err)
1212			}
1213		}
1214		recheck(busyIdx, "busy")
1215		recheck(conflictIdx, "conflict")
1216		if _, err := SubmitReview(dir, reviewSub("1", "0xa", "0xv", "sandwich", "late", "op", "r", ReviewStatusReal, 1)); !errors.Is(err, ErrReviewConflict) {
1217			t.Fatalf("fresh follower with stale base: got %v, want ErrReviewConflict", err)
1218		}
1219	
1220		// Deterministic late entrants: sequential submissions issued only after
1221		// the object is provably at version 2 and the race lock is long released.
1222		// Each acquires the free lock, reads the already-bumped version and must
1223		// take the version-conflict path (never busy, since submissions are
1224		// serialized here). This is the legitimate loser outcome the old
1225		// regression assumed could never happen, and it must append nothing.
1226		const lateN = 6
1227		for j := 0; j < lateN; j++ {
1228			_, err := SubmitReview(dir, reviewSub("1", "0xa", "0xv", "sandwich",
1229				fmt.Sprintf("late-%02d", j),
1230				fmt.Sprintf("late-operator-%02d", j),
1231				fmt.Sprintf("late-reason-%02d", j),
1232				contenderStatuses[j%len(contenderStatuses)], 1))
1233			if !errors.Is(err, ErrReviewConflict) {
1234				t.Fatalf("late entrant %d after lock release: got %v, want ErrReviewConflict", j, err)
1235			}
1236		}
1237	
1238		// The follow-up conflict submissions appended nothing either.
1239		final, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1240		if err != nil {
1241			t.Fatal(err)
1242		}
1243		if final.Version != 2 || len(final.Revisions) != 2 || !reflect.DeepEqual(final.Revisions, hist.Revisions) {
1244			t.Fatalf("post-race conflict replays changed history: %+v", final)
1245		}
1246		return winner
1247	}
