1383	func TestSubmitReviewFailureLeavesNoHalfRevision(t *testing.T) {
1384		dir := t.TempDir()
1385		mustReplay(t, dir, twoFindingsInput)
1386		before, err := os.ReadFile(filepath.Join(dir, archiveFileName))
1387		if err != nil {
1388			t.Fatal(err)
1389		}
1390		// Unknown conclusion fails validation against archive content and must
1391		// not append anything.
1392		if _, err := SubmitReview(dir, reviewSub("1", "0xa", "0xghost", "sandwich", "s", "a", "r", ReviewStatusReal, 0)); !errors.Is(err, ErrUnknownConclusion) {
1393			t.Fatalf("got %v, want ErrUnknownConclusion", err)
1394		}
1395		after, err := os.ReadFile(filepath.Join(dir, archiveFileName))
1396		if err != nil {
1397			t.Fatal(err)
1398		}
1399		if !reflect.DeepEqual(before, after) {
1400			t.Fatal("failed submission modified the archive")
1401		}
1402	}
1403	
1404	// breakArchiveSave makes the archive commit fail at the save stage: the
1405	// temporary file the atomic writer creates becomes a directory, so opening
1406	// it as a regular file fails while the lock, the archived conclusion, the
1407	// review object and its revisions are all valid. This is a storage failure
1408	// at persistence time, not a validation, version-conflict or busy error.
1409	func breakArchiveSave(t *testing.T, dir string) {
1410		t.Helper()
1411		tmp := filepath.Join(dir, archiveFileName+".tmp")
1412		if err := os.Mkdir(tmp, 0o755); err != nil {
1413			t.Fatalf("break archive save: %v", err)
1414		}
1415	}
