1424	func TestSubmitReviewSaveFailureRetriedAfterRecovery(t *testing.T) {
1425		dir := t.TempDir()
1426		mustReplay(t, dir, twoFindingsInput)
1427	
1428		// A pre-existing alert record must survive the failed and successful
1429		// submissions byte-for-byte in content.
1430		alertsBefore, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1)
1431		if err != nil {
1432			t.Fatal(err)
1433		}
1434		if len(alertsBefore) != 2 {
1435			t.Fatalf("setup: got %d alert records, want 2", len(alertsBefore))
1436		}
1437	
1438		// Main precondition: the object is at version 1 with a real judgment and
1439		// one complete revision.
1440		first := submit(t, dir, reviewSub("1", "0xa", "0xv", "sandwich", "s-1", "alice", "confirmed bot", ReviewStatusReal, 0))
1441		if !first.Created || first.Version != 1 {
1442			t.Fatalf("setup submission = %+v", first)
1443		}
1444	
1445		original, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1446		if err != nil {
1447			t.Fatal(err)
1448		}
1449		if original.Status != ReviewStatusReal || original.Version != 1 || len(original.Revisions) != 1 {
1450			t.Fatalf("setup object state = %+v", original)
1451		}
1452		archiveBefore, err := os.ReadFile(filepath.Join(dir, archiveFileName))
1453		if err != nil {
1454			t.Fatal(err)
1455		}
1456	
1457		// Valid target, valid content, valid expected version: the only failure
1458		// is storage failing while the new revision is being archived.
1459		breakArchiveSave(t, dir)
1460		rejudgment := reviewSub("1", "0xa", "0xv", "sandwich", "s-2", "bob", "actually a false positive", ReviewStatusFalsePositive, 1)
1461		failed, err := SubmitReview(dir, rejudgment)
1462		if err == nil {
1463			t.Fatalf("save failure must return an error, got result %+v", failed)
1464		}
1465		if errors.Is(err, ErrBusy) || errors.Is(err, ErrReviewConflict) ||
1466			errors.Is(err, ErrUnknownConclusion) || errors.Is(err, ErrSubmissionConflict) {
1467			t.Fatalf("failure must happen at the save stage, got %v", err)
1468		}
1469		if failed.Created {
1470			t.Fatalf("failed save must not report created=true: %+v", failed)
1471		}
1472		restoreArchiveSave(t, dir)
1473	
1474		// The original judgment is fully retained: still real at version 1, the
1475		// single original revision with no trace of the failed submission.
1476		after, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1477		if err != nil {
1478			t.Fatal(err)
1479		}
1480		if after.Status != ReviewStatusReal || after.Version != 1 {
1481			t.Fatalf("failed save advanced the object: %q/%d, want real/1", after.Status, after.Version)
1482		}
1483		if len(after.Revisions) != 1 {
1484			t.Fatalf("failed save left %d revisions: %+v", len(after.Revisions), after.Revisions)
1485		}
1486		if !reflect.DeepEqual(after.Revisions[0], original.Revisions[0]) {
1487			t.Fatalf("original revision changed: %+v, want %+v", after.Revisions[0], original.Revisions[0])
1488		}
1489		for _, rev := range after.Revisions {
1490			if rev.SubmissionID == "s-2" || rev.Operator == "bob" ||
1491				rev.Status == ReviewStatusFalsePositive || rev.Reason == "actually a false positive" {
1492				t.Fatalf("failed submission content leaked into history: %+v", rev)
1493			}
1494		}
1495		// The archived original conclusion, its detection version and the raw
1496		// swap evidence are untouched, as are the pre-existing alert records.
1497		if after.Original == nil ||
1498			after.Original.Finding.TxHash != "0xv" || after.Original.Finding.Kind != "sandwich" ||
1499			after.Original.Finding.Severity != 3 || len(after.Original.Finding.Evidence) != 3 {
1500			t.Fatalf("original conclusion/evidence changed: %+v", after.Original)
1501		}
1502		if after.Original.Version.ID != BuiltinVersionID {
1503			t.Fatalf("detection version changed: %+v", after.Original.Version)
1504		}
1505		archiveAfter, err := os.ReadFile(filepath.Join(dir, archiveFileName))
1506		if err != nil {
1507			t.Fatal(err)
1508		}
1509		if !reflect.DeepEqual(archiveBefore, archiveAfter) {
1510			t.Fatal("failed save modified the archive file")
1511		}
1512		alertsAfter, err := AlertHistory(dir, "1", "ops", 0, 100)
1513		if err != nil {
1514			t.Fatal(err)
1515		}
1516		if !reflect.DeepEqual(alertsBefore, alertsAfter) {
1517			t.Fatalf("alert records changed: before %+v after %+v", alertsBefore, alertsAfter)
1518		}
1519	
1520		// Storage recovered: the exact same submission, same submissionId and
1521		// still expectedVersion 1, goes through as a fresh create — the failed
1522		// attempt must neither have consumed the submission id nor count as a
1523		// stored duplicate.
1524		retry, err := SubmitReview(dir, rejudgment)
1525		if err != nil {
1526			t.Fatalf("retry after recovery: %v", err)
1527		}
1528		if !retry.Created || retry.Version != 2 || retry.Status != ReviewStatusFalsePositive {
1529			t.Fatalf("retry = %+v, want created=true at version 2", retry)
1530		}
1531		wantRev := rejudgment.revision(2)
1532		if !reflect.DeepEqual(retry.Revision, wantRev) {
1533			t.Fatalf("saved revision = %+v, want %+v", retry.Revision, wantRev)
1534		}
1535	
1536		saved, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1537		if err != nil {
1538			t.Fatal(err)
1539		}
1540		if saved.Status != ReviewStatusFalsePositive || saved.Version != 2 || len(saved.Revisions) != 2 {
1541			t.Fatalf("object after retry = %q/%d with %d revisions", saved.Status, saved.Version, len(saved.Revisions))
1542		}
1543		if !reflect.DeepEqual(saved.Revisions[0], original.Revisions[0]) {
1544			t.Fatalf("original revision not retained first: %+v", saved.Revisions[0])
1545		}
1546		if !reflect.DeepEqual(saved.Revisions[1], wantRev) {
1547			t.Fatalf("appended revision = %+v, want %+v", saved.Revisions[1], wantRev)
1548		}
1549	
1550		// Sending the now-successful submission verbatim a second time is the
1551		// ordinary idempotent retry: created:false, the first successfully saved
1552		// revision returned, history unchanged.
1553		again, err := SubmitReview(dir, rejudgment)
1554		if err != nil {
1555			t.Fatalf("verbatim resend: %v", err)
1556		}
1557		if again.Created {
1558			t.Fatal("verbatim resend of a stored submission must report created=false")
1559		}
1560		if !reflect.DeepEqual(again.Revision, wantRev) || again.Version != 2 || again.Status != ReviewStatusFalsePositive {
1561			t.Fatalf("resend result = %+v", again)
1562		}
1563		final, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1564		if err != nil {
1565			t.Fatal(err)
1566		}
1567		if final.Version != 2 || len(final.Revisions) != 2 {
1568			t.Fatalf("verbatim resend changed history: version %d, %d revisions", final.Version, len(final.Revisions))
1569		}
1570		if !reflect.DeepEqual(final.Revisions, saved.Revisions) {
1571			t.Fatalf("verbatim resend appended a revision: %+v", final.Revisions)
1572		}
1573	}
