289		rewriteStoredReportVersion(t, dir2, "1", "0xblk", func(ver map[string]any) {
290			storedRule(t, ver, "displacement")["multiplier"] = 0
291		})
292		assertCompareRefused(t, dir2, "1", "0xblk", "twin", "candC", "multiplier")
293	
294		// A complete declaration with an id the registry never carried is
295		// valid on its own and needs no registry backing.
296		dir3 := setupCorruptCompareArchive(t)
297		stray := map[string]any{
298			"id": "never-registered",
299			"rules": map[string]any{
300				"sandwich":     map[string]any{"enabled": true, "severity": 5},
301				"displacement": map[string]any{"enabled": true, "severity": 5, "multiplier": 9},
302			},
303		}
304		replaceStoredReportVersion(t, dir3, "1", "0xblk", stray)
305		r3, err := Compare(dir3, "1", "0xblk", "twin")
306		if err != nil {
307			t.Fatalf("a complete self-contained declaration must not need registry backing: %v", err)
308		}
309		if r3.OriginalVersion.ID != "never-registered" ||
310			r3.OriginalVersion.Rules.Displacement.Multiplier != 9 {
311			t.Fatalf("saved historical parameters not carried: %+v", r3.OriginalVersion)
312		}
313	}
