26	// in one archived record (not the versions-registry entry).
27	func corruptStoredReportVersion(t *testing.T, dir, chain, hash string, mutate func(rec map[string]any)) {
28		t.Helper()
29		path := filepath.Join(dir, "archive.json")
30		raw, err := os.ReadFile(path)
31		if err != nil {
32			t.Fatal(err)
33		}
