35		if err := json.Unmarshal(raw, &doc); err != nil {
36			t.Fatal(err)
37		}
38		for _, r := range doc["records"].([]any) {
39			rec := r.(map[string]any)
40			if rec["chainId"] == chain && rec["blockHash"] == hash {
41				mutate(rec)
42				out, err := json.MarshalIndent(doc, "", "  ")
43				if err != nil {
44					t.Fatal(err)
45				}
46				if err := os.WriteFile(path, out, 0o644); err != nil {
47					t.Fatal(err)
48				}
49				return
50			}
51		}
52		t.Fatalf("record %s/%s not found in archive", chain, hash)
53	}
