55	// TestCLICompareCorruptHistoricalDeclaration pins the CLI failure
56	// shape for a damaged historical declaration while the candidate
57	// (candC) stays perfectly legal.
58	func TestCLICompareCorruptHistoricalDeclaration(t *testing.T) {
59		dir := setupCLIArchive(t)
60	
61		// The report was archived under archA; drop the displacement
62		// multiplier only from its embedded declaration while the
63		// registered archA entry and the candC candidate stay intact.
64		corruptStoredReportVersion(t, dir, "1", "0xblk", func(rec map[string]any) {
65			ver := rec["version"].(map[string]any)
66			rules := ver["rules"].(map[string]any)
67			disp := rules["displacement"].(map[string]any)
68			delete(disp, "multiplier")
69		})
70	
71		res := runCLI(t, "compare", dir, "1", "0xblk", "candC")
72		if res.exitCode != 1 {
73			t.Fatalf("exit = %d, want 1; stdout=%q stderr=%q", res.exitCode, res.stdout, res.stderr)
74		}
75		if res.stdout != "" {
76			t.Fatalf("corrupt historical declaration must print no comparison JSON, got %q", res.stdout)
77		}
78		for _, want := range []string{
79			"corrupt",      // ErrCorruptVersion
80			"chain 1",      // target chain
81			"block 0xblk",  // target block
82			"archA",        // readable historical version id
83			"multiplier",   // offending field
84			"displacement", // offending rule
85		} {
86			if !strings.Contains(res.stderr, want) {
87				t.Fatalf("stderr = %q, want substring %q", res.stderr, want)
88			}
89		}
90		if strings.Contains(res.stderr, "goroutine") || strings.Contains(res.stderr, "runtime error") {
91			t.Fatalf("compare crashed instead of failing cleanly: %q", res.stderr)
92		}
93	
94		// A legal candidate can never rescue the historical declaration:
95		// the intact builtin and liveB candidates fail the same way.
96		for _, candidate := range []string{"builtin", "liveB"} {
97			again := runCLI(t, "compare", dir, "1", "0xblk", candidate)
98			if again.exitCode != 1 || again.stdout != "" ||
99				!strings.Contains(again.stderr, "corrupt") ||
100				!strings.Contains(again.stderr, "archA") {
101				t.Fatalf("candidate %s must not rescue the corrupt report: exit=%d stdout=%q stderr=%q",
102					candidate, again.exitCode, again.stdout, again.stderr)
103			}
104		}
105	
106		// Unknown block and unknown candidate keep their existing error
107		// behavior instead of becoming corruption errors.
108		missingBlock := runCLI(t, "compare", dir, "1", "0xghost", "candC")
109		if missingBlock.exitCode != 1 || !strings.Contains(missingBlock.stderr, "unknown block") ||
110			strings.Contains(missingBlock.stderr, "corrupt") {
