	"testing"

	"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
)

const cliHelperEnv = "MEVWATCH_TEST_HELPER"

// cliResult is the captured outcome of one forked CLI invocation.
type cliResult struct {
	stdout   string
	stderr   string
