	if hist.exitCode != 0 || !strings.Contains(hist.stdout, `"status":"false_positive"`) {
		t.Fatalf("review history changed after refused evaluation: exit=%d stdout=%q stderr=%q",
			hist.exitCode, hist.stdout, hist.stderr)
	}

